import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, PointLight } = ctx.THREE;
  const group = new Group();

  // 1. Stage Backdrop (z = -2.5) holding the vertical gradient stops
  const bgGeom = new PlaneGeometry(8, 6);
  const bgMat = new MeshBasicNodeMaterial();

  const vUv = uv();
  const topColor = color('#16161d'); // Primary Ink
  const bottomColor = color('#0b0b10'); // Surface near-black
  bgMat.colorNode = mix(bottomColor, topColor, vUv.y);

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -2.5;
  group.add(bgMesh);

  // 2. Local Rim Light to emphasize the machined metal aesthetic
  const rimLight = new PointLight('#ff2a38', 1.4, 6); // Signal Red Accent
  rimLight.position.set(2.5, 2, 0.5);
  group.add(rimLight);

  // 3. Central Textured Feature Card Plane
  const cardGeom = new PlaneGeometry(3.6, 2.25);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.52,
    metalness: 0.55,
    transparent: true,
    opacity: 0.95
  });

  const cardMesh = new Mesh(cardGeom, cardMat);
  cardMesh.position.set(0, 0.2, 0);
  group.add(cardMesh);

  // Contact shadow representation underneath the feature card
  const shadowGeom = new PlaneGeometry(3.8, 0.4);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.6
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -1.0, -0.05);
  shadowMesh.rotation.x = -Math.PI * 0.45;
  group.add(shadowMesh);

  // Load Image Asset safely through the specific textureLoader
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    }).catch((err) => console.warn('Could not load image asset:', err));
  }

  // 4. Render Spec Text via Font Atlas (Display / Mono Scale)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textString = textItems[0]?.text ?? "A machined-metal watch atelier landing with catalog, pricing, jo";

  const textObj = ctx.fontAtlas.createText(textString, {
    fontSize: 0.11, // Structured caption/body sizing scale
    color: '#e8ecf2', // Paper white for extreme legibility
    align: 'center',
    maxWidthPx: 560
  });
  textObj.position.set(0, -1.3, 0.15);
  group.add(textObj);

  // 5. Entrance Timelines & Weight Motion
  const tl = gsap.timeline();

  // Animate card slide with weighted-settle signature feel
  tl.fromTo(cardMesh.position, 
    { y: -0.2, z: -0.4 }, 
    { y: 0.2, z: 0, duration: 1.1, ease: "power4.out" }
  );

  tl.fromTo(cardMesh.rotation, 
    { x: -0.08 }, 
    { x: 0, duration: 1.1, ease: "power4.out" }, 
    "<"
  );

  // Subtle delayed emergence of text
  tl.fromTo(textObj.position,
    { y: -1.45 },
    { y: -1.3, duration: 0.9, ease: "power3.out" },
    "-=0.7"
  );

  // 6. Mandatory Cleanup Hook
  group.userData = {
    cleanup: () => {
      tl.kill();
      bgGeom.dispose();
      bgMat.dispose();
      cardGeom.dispose();
      cardMat.dispose();
      shadowGeom.dispose();
      shadowMat.dispose();
    }
  };

  return group;
}
